<?php $payload=$trackingPayload; ?>
<?php $money=fn($n)=>app(\App\Support\StorefrontCurrencyContext::class)->formatSnapshot($n,$payload['currency'],$payload['currencyExchangeRate']??1); ?>
<header class="lgc-tracking-result-header"><p class="lgc-eyebrow">Order tracking</p><h1>Order {{ $payload['number'] }}</h1><p>Track the progress of your order below.</p><span class="lgc-status">{{ $payload['statusLabel'] }}</span></header>
