 $eventTitles=collect($payload['timeline'])->pluck('title')->map(fn($title)=>strtolower($title));
 $stages=['received'=>['Order received',['order received','order created','order placed']], 'payment'=>['Payment confirmed',['payment confirmed','payment received','payment completed']], 'preparing'=>['Preparing',['processing','preparing','order processing']], 'shipped'=>['Dispatched',['shipped','dispatched','in transit']], 'delivered'=>['Delivered',['delivered']]];
@endphp
<ol class="lgc-tracking-stages" aria-label="Order progress">@foreach($stages as $key=>[$label,$events])
 <?php $completed=$eventTitles->contains(fn($title)=>in_array($title,$events,true)); ?>
 <li @class(['complete'=>$completed]) @if($completed) data-stage-completed="{{ $key }}" @endif><span aria-hidden="true">{{ $completed?'✓':$loop->iteration }}</span><strong>{{ $label }}</strong><small>{{ $completed?'Confirmed':'Awaiting update' }}</small></li>
@endforeach</ol>
