<div class="lgc-tracking-info"><section><h3>Order details</h3><p>Order status: {{ $payload['statusLabel'] }}</p>@if($payload['tracking']['number'])<p>Tracking number: {{ $payload['tracking']['number'] }}</p>@endif @if($payload['tracking']['carrier'])<p>Courier: {{ $payload['tracking']['carrier'] }}</p>@endif</section><section><h3>Shipping address</h3>@if($payload['address']??null)<address>{{ $payload['address']['line1'] }}<br>{{ $payload['address']['city'] }} {{ $payload['address']['postalCode'] }}</address>@else<p>Address unavailable.</p>@endif</section></div>
</div><div><section class="lgc-tracking-updates"><h2>Shipping updates</h2>@forelse($payload['timeline'] as $event)<article><h3>{{ $event['title'] }}</h3>@if($event['timestamp'])<time>{{ \Carbon\Carbon::parse($event['timestamp'])->format('d M Y H:i') }}</time>@endif<p>{{ $event['description'] }}</p>@if($event['location'])<small>{{ $event['location'] }}</small>@endif</article>@empty<p>No shipping updates yet.</p>@endforelse</section><section class="lgc-tracking-summary"><h3>Total</h3><dl>@foreach(['subtotal'=>'Subtotal','discount'=>'Discount','shipping'=>'Shipping','tax'=>'Tax','total'=>'Total'] as $key=>$label)@if(in_array($key,['subtotal','shipping','total'])||($payload['totals'][$key]??0))<div><dt>{{ $label }}</dt><dd>{{ $money($payload['totals'][$key]??0) }}</dd></div>@endif@endforeach</dl></section></div></div><a class="lgc-primary lgc-tracking-continue" href="{{ route('storefront.index') }}">Continue shopping →</a>
